from typing import Any, Mapping
from biosim import (AcceptedSignalProfile, BioModule, BioSignal, ExecutionContext, ExecutionPolicy, SignalSpec)

UNIT = 'replace-with-real-unit'

class Component(BioModule):
    execution_policy = ExecutionPolicy.EACH_WINDOW

    def __init__(self):
        self.time = 0.0
        self.latest = None

    def inputs(self):
        profile = AcceptedSignalProfile(
            signal_type='scalar', dtype='float64', accepted_units=(UNIT,)
        )
        return {'x': SignalSpec.scalar(
            dtype='float64', accepted_profiles=(profile,)
        )}

    def outputs(self):
        return {'y': SignalSpec.scalar(
            dtype='float64', emitted_unit=UNIT
        )}

    def execute(
        self, inputs: Mapping[str, BioSignal], *, context: ExecutionContext
    ) -> Mapping[str, Any | BioSignal]:
        self.time = context.simulated_time
        self.latest = inputs.get('x')
        return {} if self.latest is None else {'y': float(self.latest.value)}

    def snapshot(self):
        return {'time': self.time}

    def restore(self, snapshot):
        self.time = float(snapshot['time'])
